    ("portal.hero_title", "app", "The operating system for commercial shipping", "商业航运操作系统"),
    ("portal.hero_sub", "app", "A calm, connected workspace for owners, charterers, operators and ship managers — from fixture to settlement.", "面向船东、租家、操作与船管的沉稳协作空间 — 从成交到结算。"),
    ("portal.why_title", "app", "Why teams choose MariOS", "为什么选择 MariOS"),
    ("portal.why_sub", "app", "Not a catalogue of screens — a clearer way to run the commercial voyage together.", "不是屏幕目录，而是一起把商业航次跑清楚的方式。"),
    ("portal.promo.clarity.title", "app", "One place for the commercial voyage", "商业航次一处办完"),
    ("portal.promo.clarity.body", "app", "Bring chartering, operations and settlement into a single daily workspace — less switching, clearer accountability.", "把租船、操作与结算放进同一日常工作台 — 少切换，责任更清。"),
    ("portal.promo.trust.title", "app", "Built for maritime teams", "为航运团队而建"),
    ("portal.promo.trust.body", "app", "Designed around how shipping desks actually work: roles, approvals, local time, and the language of the trade.", "按航运台面真实工作方式设计：角色、审批、本地时间与行业用语。"),
    ("portal.promo.connect.title", "app", "Connected to how you collaborate", "贴合你们已有的协作方式"),
    ("portal.promo.connect.body", "app", "Fit into your organisation’s identity and Microsoft 365 ways of working, without forcing a new collaboration stack.", "融入企业身份与 Microsoft 365 协作习惯，不必强行换一套协作工具。"),
    ("portal.sec.os.title", "app", "Not another shipping spreadsheet", "不是又一个航运表格工具"),
    ("portal.sec.os.body", "app", "MariOS is a maritime commercial operating system: estimate → fixture → voyage → laytime → finance → twin, with approvals and audit in the same shell.", "MariOS 是航运商业操作系统：估算→成交→航次→滞期→财务→孪生，审批与审计同壳完成。"),
    ("portal.sec.saas.title", "app", "Built as a real SaaS platform", "真正的 SaaS 平台架构"),
    ("portal.sec.saas.body", "app", "Developer plane for plans, AI metering and payments. Tenant plane for brand, org chart, roles, permissions, subscription and top-ups.", "开发商平面管理套餐、AI 计量与支付；租户平面管理品牌、组织、角色、权限、订阅与充值。"),
    ("portal.sec.flow.title", "app", "Process automation, not CRUD theatre", "流程自动化，而非 CRUD 摆设"),
    ("portal.sec.flow.body", "app", "Charter and invoice approvals run as enterprise workflows. Roles see only their desk — Chartering Day, Ops Night, Finance Desk.", "租约与发票审批走企业工作流。角色只看自己的台面——租船日班、操作夜班、财务台。"),
    ("portal.sec.scale.title", "app", "One product from solo to group", "从个体到集团同一产品"),
    ("portal.sec.scale.body", "app", "Profile tiers change density, not feature cuts. OmniSearch (Ctrl+K) keeps every document one keystroke away.", "档位改变信息密度而非砍功能。OmniSearch（Ctrl+K）一键直达单据。"),
